import {MAP,INFRA,STAGES} from './content.mjs';
import {port,distance} from './navigation.mjs';
export class Renderer{
 constructor(canvas){this.canvas=canvas;this.ctx=canvas.getContext('2d');this.camera={x:12,y:9};this.scale=37;this.follow=true;this.width=0;this.height=0;this.lastSize='';}
 resize(){const r=this.canvas.getBoundingClientRect(),d=window.devicePixelRatio||1,key=`${r.width}/${r.height}/${d}`;if(key!==this.lastSize){this.width=r.width;this.height=r.height;this.canvas.width=r.width*d;this.canvas.height=r.height*d;this.ctx.setTransform(d,0,0,d,0,0);this.lastSize=key;if(!this.initial){this.fit();this.initial=true;}}}
 fit(){this.scale=Math.min((this.width-130)/24,(this.height-170)/18,42);this.scale=Math.max(this.scale,window.innerWidth<600?25:18);this.camera={x:12,y:9};this.follow=window.innerWidth<600;}
 screen(p){return{x:(p.x-this.camera.x)*this.scale+this.width/2,y:(p.y-this.camera.y)*this.scale+this.height/2};}
 world(x,y){return{x:(x-this.width/2)/this.scale+this.camera.x,y:(y-this.height/2)/this.scale+this.camera.y};}
 draw(e,ui){this.resize();const w=e.w,c=this.ctx,s=this.scale,p=w.actors.player;
 if(this.follow&&!ui.build){const small=this.width<800;let cx=small?p.x:12,cy=small?p.y:9;this.camera.x+=(cx-this.camera.x)*.13;this.camera.y+=(cy-this.camera.y)*.13;}
 c.clearRect(0,0,this.width,this.height);c.fillStyle='#f5f5f5';c.fillRect(0,0,this.width,this.height);
 c.save();c.translate(this.width/2-this.camera.x*s,this.height/2-this.camera.y*s);c.scale(s,s);
 c.fillStyle='#fff';c.fillRect(1,1,22,16);c.strokeStyle='#ececec';c.lineWidth=1/s;c.beginPath();for(let x=1;x<=23;x++){c.moveTo(x,1);c.lineTo(x,17);}for(let y=1;y<=17;y++){c.moveTo(1,y);c.lineTo(23,y);}c.stroke();
 c.strokeStyle='#b7b7b7';c.lineWidth=3/s;c.strokeRect(1,1,22,16);
 c.fillStyle='#f0f0f0';c.fillRect(1.06,13,2.94,3.94);this.text('入口 / 安全區',2.5,16.5,.24,'#919191');
 for(const st of INFRA){c.fillStyle='#efefef';c.fillRect(st.x+.08,st.y+.08,st.w-.16,st.h-.16);c.strokeStyle=ui.selected===st.id?'#313131':'#bdbdbd';c.lineWidth=(ui.selected===st.id?2:1)/s;c.strokeRect(st.x+.08,st.y+.08,st.w-.16,st.h-.16);this.text(st.label,st.x+st.w/2,st.y+.66,.32,'#4c4c4c');this.text(st.id==='warehouse'?'MATERIALS':'DISPATCH',st.x+st.w/2,st.y+1.04,.17,'#8f8f8f');for(let n=0;n<st.capacity;n++){const col=n%(st.id==='warehouse'?6:2),row=Math.floor(n/6),xx=st.x+.35+col*(st.id==='warehouse'?.41:1.25),yy=st.y+1.35+row*.25;c.fillStyle=w.storages[st.id][n]?'#696969':'#d7d7d7';c.fillRect(xx,yy,.24,.15);}this.port(st.port);}
 if(Object.keys(w.machines).length<5&&!ui.build){const pos=[[5,5],[9,5],[13,5],[17,5],[17,10]];for(const [n,definition] of ['dep','litho','etch','clean','inspect'].entries())if(!Object.values(w.machines).some(m=>m.definitionId===definition)){let[x,y]=pos[n];c.setLineDash([.12,.15]);c.strokeStyle='#d7d7d7';c.lineWidth=1/s;c.strokeRect(x+.1,y+.1,1.8,1.8);c.setLineDash([]);this.text(`＋ ${e.c.machines[definition].label}`,x+1,y+1,.23,'#a1a1a1');}}
 for(const [actorId,data] of Object.entries(e.paths)){const a=w.actors[actorId];c.beginPath();c.moveTo(a.x,a.y);for(const pt of data.points)c.lineTo(pt.x,pt.y);c.setLineDash([.10,.14]);c.strokeStyle=actorId==='worker'?'#a1a1a1':'#c0c0c0';c.lineWidth=1/s;c.stroke();c.setLineDash([]);}
 for(const m of Object.values(w.machines)){const d=e.c.machines[m.definitionId],sel=ui.selected===m.id,progress=m.job&&w.jobs[m.job];c.fillStyle='#f5f5f5';c.fillRect(m.x+.06,m.y+.06,1.88,1.88);c.strokeStyle=sel?'#2d2d2d':'#9c9c9c';c.lineWidth=(sel?2:1)/s;c.strokeRect(m.x+.06,m.y+.06,1.88,1.88);c.fillStyle='#e7e7e7';c.fillRect(m.x+.12,m.y+.12,1.76,.37);this.text(`${d.no}  ${d.label}`,m.x+1,m.y+.37,.23,'#4e4e4e');this.machineIcon(d.capability,m.x+1,m.y+1.03);let status=m.phase==='EMPTY'?'空槽':m.phase==='RUNNING'?`${Math.ceil(progress.remaining/60)}s`:m.phase==='DONE'?'完成待取':m.phase==='HOLD'?'隔離待取':'已上料';this.text(status,m.x+1,m.y+1.70,.21,'#696969');if(m.level===2)this.text('Ⅱ',m.x+1.73,m.y+.78,.21,'#5f5f5f');if(m.phase==='RUNNING'){c.fillStyle='#d6d6d6';c.fillRect(m.x+.15,m.y+1.83,1.7,.05);c.fillStyle='#5d5d5d';c.fillRect(m.x+.15,m.y+1.83,1.7*(1-progress.remaining/progress.duration),.05);}this.port(port(m));if(m.slot)this.box(w.items[m.slot],m.x+1.45,m.y+1.08,w,false);}
 for(const i of Object.values(w.items))if(i.location.type==='ground')this.box(i,i.location.x,i.location.y,w,true);
 for(const a of Object.values(w.actors)){c.save();c.translate(a.x,a.y);c.fillStyle=a.kind==='player'?'#303030':'#fff';c.strokeStyle='#545454';c.lineWidth=2/s;c.beginPath();c.arc(0,0,.24,0,Math.PI*2);c.fill();c.stroke();c.fillStyle=a.kind==='player'?'#fff':'#545454';c.beginPath();c.arc(0,-.055,.065,0,Math.PI*2);c.fill();c.fillRect(-.075,.06,.15,.04);c.restore();this.text(a.kind==='player'?'你':'搬運工',a.x,a.y+.58,.22,'#545454');if(a.carried)this.box(w.items[a.carried],a.x+.38,a.y-.30,w,true);if(a.action){const act=w.actions[a.action];c.strokeStyle='#363636';c.lineWidth=2/s;c.beginPath();c.arc(a.x,a.y,.35,-Math.PI/2,-Math.PI/2+Math.PI*2*(1-act.remaining/15));c.stroke();}}
 if(ui.build){const b=ui.build,valid=e.check({type:b.id?'moveMachine':'place',target:b.id,definition:b.definition,x:b.x,y:b.y,rotation:b.rotation}).ok;c.fillStyle=valid?'#57575722':'#22222220';c.fillRect(b.x,b.y,2,2);c.strokeStyle=valid?'#555555':'#272727';c.lineWidth=2/s;c.setLineDash([.2,.1]);c.strokeRect(b.x,b.y,2,2);c.setLineDash([]);this.text(e.c.machines[b.definition].label,b.x+1,b.y+1,.3,'#404040');this.port(port(b));}
 c.restore();}
 text(str,x,y,size,color){const c=this.ctx;c.font=`${size}px -apple-system, sans-serif`;c.fillStyle=color;c.textAlign='center';c.textBaseline='middle';c.fillText(str,x,y);}
 port(p){const c=this.ctx;c.fillStyle='#fff';c.strokeStyle='#a2a2a2';c.lineWidth=1/this.scale;c.beginPath();c.arc(p.x,p.y,.15,0,Math.PI*2);c.fill();c.stroke();c.beginPath();c.moveTo(p.x-.07,p.y);c.lineTo(p.x+.07,p.y);c.moveTo(p.x,p.y-.07);c.lineTo(p.x,p.y+.07);c.stroke();}
 machineIcon(type,x,y){const c=this.ctx;c.save();c.translate(x,y);c.lineWidth=1/this.scale;c.strokeStyle='#999999';c.fillStyle='#c3c3c3';if(type==='dep'){for(let n=0;n<3;n++){c.beginPath();c.ellipse(0,.1-n*.14,.40,.13,0,0,Math.PI*2);c.stroke();}}else if(type==='litho'){c.strokeRect(-.35,-.3,.7,.55);for(let n=0;n<3;n++){c.beginPath();c.moveTo(-.22+n*.22,-.4);c.lineTo(-.22+n*.22,.4);c.stroke();}}else if(type==='etch'){for(let n=0;n<3;n++)c.strokeRect(-.42+n*.31,-.2,.18,.4);}else if(type==='clean'){for(let n=0;n<3;n++){c.beginPath();c.moveTo(-.4,-.22+n*.2);c.bezierCurveTo(-.15,-.42+n*.2,.15,.02+n*.2,.4,-.22+n*.2);c.stroke();}}else{c.beginPath();c.arc(-.06,-.06,.27,0,Math.PI*2);c.moveTo(.13,.13);c.lineTo(.4,.4);c.stroke();}c.restore();}
 box(i,x,y,w,label){const c=this.ctx;c.fillStyle='#fff';c.strokeStyle='#484848';c.lineWidth=1.5/this.scale;c.fillRect(x-.19,y-.17,.38,.34);c.strokeRect(x-.19,y-.17,.38,.34);if(i.kind==='wafer_lot'){c.beginPath();c.arc(x,y,.1,0,Math.PI*2);c.stroke();}else if(i.kind==='tool'){c.strokeRect(x-.1,y-.1,.2,.2);}else{c.beginPath();c.moveTo(x-.09,y);c.lineTo(x+.09,y);c.stroke();}if(label)this.text(i.lotId||i.id,x,y-.34,.17,'#5c5c5c');}
}
